<template><div><section v-if="!active" class="panel"><div class="panel-title"><h2>{{$t("我的接诊患者")}}</h2><el-button size="small" icon="el-icon-refresh" @click="load">{{$t("刷新队列")}}</el-button></div><div class="toolbar"><el-input v-model.trim="q" clearable :placeholder="$t('按姓名 / 病历号查询')" @keyup.enter.native="load"/><el-button @click="load">{{$t("查询")}}</el-button></div><el-table :data="rows" v-loading="loading" stripe><el-table-column prop="case_number" :label="$t('病历号')" width="150"/><el-table-column prop="real_name" :label="$t('患者')" width="110"/><el-table-column :formatter="localizedCell" prop="doctor" :label="$t('医生')" width="110"/><el-table-column :label="$t('状态')" width="110"><template slot-scope="s"><el-tag size="small" :type="s.row.visit_state==='COMPLETED'?'success':'warning'">{{$t(state(s.row.visit_state))}}</el-tag></template></el-table-column><el-table-column :label="$t('挂号时间')" min-width="180"><template slot-scope="s">{{$t(date(s.row.created_at))}}</template></el-table-column><el-table-column :label="$t('操作')" width="130"><template slot-scope="s"><el-button :loading="selectingId===s.row.id" :disabled="selectingId!==null" v-if="s.row.visit_state!=='CANCELLED'" type="text" @click="select(s.row)">{{$t(s.row.visit_state==='WAITING'?'开始接诊':'诊疗工作台')}}</el-button></template></el-table-column></el-table></section><template v-if="active"><div class="panel-title"><h2 ref="workspaceHeading" tabindex="-1">{{$t("当前患者：")}}{{active.real_name}}（{{active.case_number}}）</h2><el-button icon="el-icon-back" @click="closeWorkspace">{{$t("返回患者列表")}}</el-button></div><el-tabs v-model="tab" type="border-card" class="clinical-tabs"><el-tab-pane :label="$t('病历首页 / 确诊')" name="record"><el-alert :title="$t('就诊顺序：保存病历首页 → 按需申请检查/检验 → 录入确诊 → 开立处方/处置')" type="info" :closable="false" show-icon/><el-form label-position="top" style="margin-top:18px"><div class="form-grid"><el-form-item :label="$t('主诉')"><el-input v-model="record.complaint" type="textarea" :rows="2" maxlength="5000"/></el-form-item><el-form-item :label="$t('现病史')"><el-input v-model="record.illness" type="textarea" :rows="2" maxlength="5000"/></el-form-item><el-form-item :label="$t('现病治疗情况')"><el-input v-model="record.treatment" type="textarea" :rows="2" maxlength="5000"/></el-form-item><el-form-item :label="$t('既往史')"><el-input v-model="record.past" type="textarea" :rows="2" maxlength="5000"/></el-form-item><el-form-item :label="$t('过敏史')"><el-input v-model="record.allergies" type="textarea" :rows="2" maxlength="5000"/></el-form-item><el-form-item :label="$t('体格检查')"><el-input v-model="record.exam" type="textarea" :rows="2" maxlength="5000"/></el-form-item><el-form-item :label="$t('初步诊断')"><el-input v-model="record.preliminary" maxlength="500"/></el-form-item><el-form-item :label="$t('检查/检验建议')"><el-input v-model="record.suggestions" maxlength="5000"/></el-form-item><el-form-item class="full-width"><el-button type="primary" :disabled="active.visit_state==='COMPLETED'" @click="saveRecord">{{$t("保存病历首页")}}</el-button></el-form-item></div><el-divider content-position="left">{{$t("门诊确诊")}}</el-divider><div class="form-grid"><el-form-item :label="$t('确诊结果')" required><el-input v-model="diagnosis" maxlength="500"/></el-form-item><el-form-item :label="$t('治疗意见')" required><el-input v-model="plan" maxlength="5000"/></el-form-item></div><el-button type="success" :disabled="active.visit_state!=='IN_PROGRESS'" @click="finalize">{{$t("提交确诊")}}</el-button></el-form></el-tab-pane><el-tab-pane :label="$t('检查 / 检验 / 处置申请')" name="service"><el-form label-position="top"><div class="form-grid"><el-form-item :label="$t('项目类型')"><el-select v-model="service.type" class="full" @change="getCatalog"><el-option :label="$t('检查')" value="CHECK"/><el-option :label="$t('检验')" value="LAB"/><el-option :label="$t('处置（需先确诊）')" value="PROCEDURE"/></el-select></el-form-item><el-form-item :label="$t('具体项目')"><el-select v-model="service.projectId" class="full" filterable :placeholder="$t('选择医技项目')"><el-option v-for="p in projects" :key="p.id" :value="p.id" :label="$t(`${p.project_name} · ¥${p.unit_price}`)"/></el-select></el-form-item><el-form-item :label="$t('目的要求')"><el-input v-model="service.purpose"/></el-form-item><el-form-item :label="$t('检查 / 处置部位')"><el-input v-model="service.position"/></el-form-item><el-form-item class="full-width" :label="$t('备注')"><el-input v-model="service.note" type="textarea" :rows="2"/></el-form-item></div><el-button type="primary" @click="requestService">{{$t("开立申请")}}</el-button></el-form><el-divider/><h3>{{$t("患者医技记录与结果")}}</h3><el-tabs v-model="resultTab" @tab-click="getResults"><el-tab-pane :label="$t('检查')" name="CHECK"/><el-tab-pane :label="$t('检验')" name="LAB"/><el-tab-pane :label="$t('处置')" name="PROCEDURE"/></el-tabs><el-table :data="resultRows" stripe><el-table-column prop="project_name" :label="$t('项目')"/><el-table-column prop="status" :label="$t('执行状态')" width="120"/><el-table-column prop="payment_status" :label="$t('缴费')" width="110"/><el-table-column prop="result" :label="$t('结果')"><template slot-scope="s">{{s.row.result||'尚未出结果'}}</template></el-table-column><el-table-column :label="$t('操作')" width="95"><template slot-scope="s"><el-button v-if="s.row.status==='CREATED'&&['UNPAID','REFUNDED'].includes(s.row.payment_status)" type="text" @click="cancelService(s.row)">{{$t("撤销申请")}}</el-button></template></el-table-column></el-table></el-tab-pane><el-tab-pane :label="$t('开立处方')" name="prescription"><el-alert type="info" :closable="false" :title="$t('确诊完成后可开立处方；收费员完成缴费后药房才能发药。')"/><el-form label-position="top"><div class="form-grid"><el-form-item :label="$t('选择药品')"><el-select v-model="newDrug.drugId" class="full" filterable :placeholder="$t('搜索药品')"><el-option v-for="d in drugs" :key="d.id" :value="d.id" :label="$t(`${d.drug_name} · ¥${d.unit_price} · 库存${d.stock}`)"/></el-select></el-form-item><el-form-item :label="$t('数量')"><el-input-number v-model="newDrug.quantity" :min="1" :max="10000"/></el-form-item><el-form-item :label="$t('单次用量')"><el-input v-model="newDrug.dosage" :placeholder="$t('例如：1片')"/></el-form-item><el-form-item :label="$t('频次')"><el-input v-model="newDrug.frequency" :placeholder="$t('例如：每日两次')"/></el-form-item><el-form-item :label="$t('天数')"><el-input-number v-model="newDrug.days" :min="1" :max="365"/></el-form-item><el-form-item :label="$t('用药嘱托')"><el-input v-model="newDrug.advice"/></el-form-item></div><el-button @click="addDrug">{{$t("加入处方")}}</el-button></el-form><el-table v-if="items.length" :data="items" style="margin-top:12px"><el-table-column prop="name" :label="$t('药品')"/><el-table-column prop="quantity" :label="$t('数量')"/><el-table-column prop="dosage" :label="$t('用量')"/><el-table-column prop="frequency" :label="$t('频次')"/><el-table-column :label="$t('金额')"><template slot-scope="s">¥{{$t((s.row.price*s.row.quantity).toFixed(2))}}</template></el-table-column><el-table-column :label="$t('操作')" width="75"><template slot-scope="s"><el-button type="text" @click="items.splice(s.$index,1)">{{$t("删除")}}</el-button></template></el-table-column></el-table><div class="form-footer"><strong>{{$t("处方金额：¥")}}{{$t(amount)}}</strong><el-button type="primary" :disabled="active.visit_state!=='COMPLETED'||!items.length" @click="submitPrescription">{{$t("确认开立处方")}}</el-button></div></el-tab-pane></el-tabs></template></div></template>
<script>
import api from '../api';export default{name:'Medical',data(){return{q:'',rows:[],loading:false,selectingId:null,active:null,tab:'record',record:{},diagnosis:'',plan:'',service:{type:'CHECK',projectId:null,purpose:'',position:'',note:''},projects:[],resultTab:'CHECK',resultRows:[],drugs:[],newDrug:{drugId:null,quantity:1,dosage:'',frequency:'',days:1,advice:''},items:[]}},computed:{amount(){return this.items.reduce((a,b)=>a+b.quantity*b.price,0).toFixed(2)}},created(){this.load();this.getCatalog();this.getDrugs()},methods:{date(d){return d?String(d).replace('T',' ').slice(0,19):'—'},state(s){return{WAITING:'待接诊',IN_PROGRESS:'诊疗中',COMPLETED:'已诊毕',CANCELLED:'已退号'}[s]||s},async load(){this.loading=true;try{this.rows=await api.get('/registrations',{params:{q:this.q}})}catch(e){this.$message.error(e.message)}finally{this.loading=false}},async select(r){
 if(this.selectingId!==null)return;
 this.selectingId=r.id;
 try{
  const x=await api.get(`/records/${r.id}`);
  this.record={complaint:x.chief_complaint||'',illness:x.present_illness||'',treatment:x.treatment_history||'',past:x.past_history||'',allergies:x.allergies||'',exam:x.physical_exam||'',preliminary:x.preliminary_diagnosis||'',suggestions:x.suggestions||''};
  this.diagnosis=x.final_diagnosis||'';this.plan=x.treatment_plan||'';
  this.tab='record';this.resultTab='CHECK';this.resultRows=[];
  this.items=[];this.presRequestId=null;
  this.service={type:'CHECK',projectId:null,purpose:'',position:'',note:''};
  this.newDrug={drugId:null,quantity:1,dosage:'',frequency:'',days:1,advice:''};
  this.active=r;
  this.getCatalog();this.getResults();
  await this.$nextTick();window.scrollTo({top:0,behavior:'auto'});
  if(this.$refs.workspaceHeading)this.$refs.workspaceHeading.focus({preventScroll:true});
 }catch(e){this.$message.error(e.message)}finally{this.selectingId=null}
},closeWorkspace(){this.active=null;window.scrollTo({top:0,behavior:'auto'})},async confirm(message){try{await this.$confirm(message,'操作确认',{type:'warning'});return true}catch{return false}},async saveRecord(){if(!await this.confirm('确认保存当前病历首页的修改内容？'))return;try{await api.put(`/records/${this.active.id}`,this.record);this.$message.success('病历已保存');await this.load();this.active=this.rows.find(r=>r.id===this.active.id)||this.active}catch(e){this.$message.error(e.message)}},async finalize(){if(!this.diagnosis||!this.plan)return this.$message.warning('请填写确诊结果和治疗意见');if(!await this.confirm('确认提交门诊确诊？提交后病历首页不能直接修改。'))return;try{await api.post(`/records/${this.active.id}/finalize`,{diagnosis:this.diagnosis,plan:this.plan});this.$message.success('确诊已提交');await this.load();this.active=this.rows.find(r=>r.id===this.active.id)||this.active}catch(e){this.$message.error(e.message)}},async getCatalog(){this.service.projectId=null;try{this.projects=await api.get('/catalog',{params:{type:this.service.type}})}catch(e){this.$message.error(e.message)}},async requestService(){if(!this.service.projectId)return this.$message.warning('请选择项目');if(!await this.confirm('确认开立该申请？开立后患者需先缴费。'))return;try{await api.post('/services',{...this.service,registrationId:this.active.id,requestId:this.service.requestId||(this.service.requestId=Date.now().toString(36)+Math.random().toString(36).slice(2))});this.$message.success('申请已开立');this.service.requestId=null;this.getResults()}catch(e){this.$message.error(e.message)}},async getResults(){if(!this.active)return;try{let all=await api.get('/services',{params:{type:this.resultTab}});this.resultRows=all.filter(x=>x.register_id===this.active.id)}catch(e){this.$message.error(e.message)}},async cancelService(row){if(!await this.confirm('仅未执行、未收费或已退费的申请可撤销，确定继续？'))return;try{await api.post(`/services/${this.resultTab}/${row.id}/cancel`);this.$message.success('申请已撤销');this.getResults()}catch(e){this.$message.error(e.message)}},async getDrugs(){try{this.drugs=await api.get('/drugs')}catch(e){this.$message.error(e.message)}},addDrug(){let d=this.drugs.find(x=>x.id===this.newDrug.drugId);if(!d||!this.newDrug.dosage.trim()||!this.newDrug.frequency.trim())return this.$message.warning('选择药品并填写用量、频次');this.items.push({...this.newDrug,name:d.drug_name,price:Number(d.unit_price)});this.newDrug={drugId:null,quantity:1,dosage:'',frequency:'',days:1,advice:''}},async submitPrescription(){if(!await this.confirm(`确认开立处方，总金额 ¥${this.amount}？`))return;try{await api.post('/prescriptions',{registrationId:this.active.id,items:this.items,requestId:this.presRequestId||(this.presRequestId=Date.now().toString(36)+Math.random().toString(36).slice(2))});this.items=[];this.presRequestId=null;this.$message.success('处方已开立，等待收费')}catch(e){this.$message.error(e.message)}}}}
</script>
